package zone.moddev.mc.ironagearchitecture.roof;

import java.util.*;
import net.minecraft.block.state.IBlockState;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayer;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.*;
import net.minecraft.util.EnumFacing;
import net.minecraft.util.math.*;
import net.minecraft.world.World;
import zone.moddev.mc.ironagearchitecture.*;
import zone.moddev.mc.ironagearchitecture.roof.ArchitectWorkbench.Desk;

/** Local rework with real escrow. Old material is credited only after its last fragment is removed. */
public final class RoofDesignConstruction {
    private RoofDesignConstruction(){}
    public static final class Job {
        public int removals;public RoofMaterials.Stock escrow=new RoofMaterials.Stock();public final Set<String> spent=new HashSet<>();
        final Map<String,Integer> left=new HashMap<>();final Map<String,ItemStack> recovered=new HashMap<>();boolean indexed;
        public NBTTagCompound write(){NBTTagCompound n=new NBTTagCompound();n.setInteger("removals",removals);n.setTag("escrow",escrow.write());NBTTagList ids=new NBTTagList();for(String id:spent)ids.appendTag(new NBTTagString(id));n.setTag("spent",ids);return n;}
        public static Job read(NBTTagCompound n){Job j=new Job();j.removals=n.getInteger("removals");if(j.removals<0||j.removals>RoofPlan.MAX_CELLS)throw new IllegalArgumentException("Invalid rework job");j.escrow=RoofMaterials.Stock.read(n.getTagList("escrow",10));NBTTagList s=n.getTagList("spent",8);if(s.tagCount()>8192)throw new IllegalArgumentException("Invalid spent material list");for(int i=0;i<s.tagCount();i++)j.spent.add(s.getStringTagAt(i));return j;}
    }
    public static final class Quote {
        public final RoofPlan next,old;
        public final List<Long> remove=new ArrayList<>(),place=new ArrayList<>();
        public final RoofMaterials.Stock additions=new RoofMaterials.Stock(),returns=new RoofMaterials.Stock(),reuse=new RoofMaterials.Stock();
        public String error="";
        Quote(RoofPlan p){next=p.copy();old=p.settingsCopy();old.cells.clear();}
    }
    public static List<RoofPart> paid(RoofCell c,IBlockState state,BlockPos at){if(c.designed)return c.parts;List<RoofPart> out=new ArrayList<>();int wood=state.getProperties().containsKey(RoofFrameBlock.WOOD)?state.getValue(RoofFrameBlock.WOOD):0;if(c.timber())out.add(new RoofPart("legacy-timber:"+at.toLong(),at,RoofPart.TIMBER,wood,new int[0]));int cover=RoofFrameBlock.cover(state);if(c.coverable()&&cover>0)out.add(new RoofPart("legacy-cover:"+c.owner.toLong(),c.owner,RoofPart.COVER,cover,new int[0]));return out;}
    private static Map<String,ItemStack> resources(World w,Map<Long,RoofCell> cells,Collection<Long> keys){Map<String,ItemStack> result=new HashMap<>();for(long key:keys){RoofCell c=cells.get(key);if(c==null)continue;BlockPos at=BlockPos.fromLong(key);for(RoofPart p:paid(c,w.getBlockState(at),at)){ItemStack item=RoofMaterials.item(p);if(item!=null)result.putIfAbsent(p.id,item);}}return result;}
    public static Quote quote(Desk d,RoofPlan proposed,EntityPlayer player){World w=d.getWorld();Quote q=new Quote(proposed);if(!proposed.valid()){q.error=proposed.error.isEmpty()?"Refresh the roof drawing.":proposed.error;return q;}if(!proposed.contains(d.getPos().down())){q.error="Keep the workbench inside the selected floor.";return q;}
        String supports=RoofSupports.validate(w,proposed);if(!supports.isEmpty()){q.error=supports;return q;}RoofPlan committed=RoofData.get(w).plans.get(proposed.id);if(committed!=null)q.old.cells.putAll(RoofData.get(w).owned(w,committed));q.old.cells.putAll(RoofData.get(w).owned(w,proposed));for(RoofPlan other:RoofData.get(w).plans.values())if(!other.id.equals(proposed.id)&&other.floorY==proposed.floorY&&other.minX<=proposed.maxX&&other.maxX>=proposed.minX&&other.minZ<=proposed.maxZ&&other.maxZ>=proposed.minZ){q.error="This floor area belongs to another roof.";return q;}
        for(RoofCell cell:q.old.cells.values())for(RoofWindow window:cell.windows)if(RoofData.get(w).removed(cell.plan,window.id)){q.error="Window ownership is being repaired. Try again in a moment.";return q;}
        // A bare main covering inherits its actual material. Features carry their explicit choice.
        Map<Long,Integer> legacyCover=new HashMap<>();for(Map.Entry<Long,RoofCell> e:q.old.cells.entrySet())if(!e.getValue().designed){BlockPos at=BlockPos.fromLong(e.getKey());int cover=RoofFrameBlock.cover(w.getBlockState(at));if(cover>0)legacyCover.put(RoofPlan.column(at.getX(),at.getZ()),cover);}Map<String,RoofPart> actual=new HashMap<>();Map<String,RoofWindow> panes=new HashMap<>();for(RoofCell c:q.old.cells.values()){for(RoofPart p:c.parts)actual.put(p.id,p);for(RoofWindow window:c.windows)panes.put(window.id,window);}
        for(Map.Entry<Long,RoofCell> e:new ArrayList<>(q.next.cells.entrySet())){RoofCell c=e.getValue();List<RoofPart> parts=new ArrayList<>();for(RoofPart p:c.parts){RoofPart prior=actual.get(p.id);parts.add(p.kind==RoofPart.COVER&&p.material==0&&(prior!=null||legacyCover.containsKey(RoofPlan.column(p.root.getX(),p.root.getZ())))?p.withMaterial(prior!=null?prior.material:legacyCover.get(RoofPlan.column(p.root.getX(),p.root.getZ()))):p);}List<RoofWindow> windows=new ArrayList<>();for(RoofWindow n:c.windows){RoofWindow old=panes.get(n.id);windows.add(old!=null&&old.owner.equals(n.owner)&&old.style==n.style&&old.vertical==n.vertical&&old.facing==n.facing&&old.slope32==n.slope32&&old.y32==n.y32&&old.rise32==n.rise32&&old.right==n.right&&old.joins==n.joins?n.state(old.open,old.powered):n);}q.next.cells.put(e.getKey(),new RoofCell(c.plan,c.owner,parts,windows));}
        Map<String,RoofPart> newBoards=new HashMap<>();for(RoofCell c:q.next.cells.values())for(RoofPart part:c.parts)if(part.kind==RoofPart.FASCIA)newBoards.put(part.id,part);
        for(Map.Entry<Long,RoofCell> e:q.old.cells.entrySet())for(RoofPart part:e.getValue().parts)if((part.kind==RoofPart.GUTTER&&part.id.startsWith("gutter:")||part.kind==RoofPart.SOFFIT&&part.material==6&&part.id.startsWith("lining:"))){RoofPart board=newBoards.get(part.id.substring(7)),prior=actual.get(part.id.substring(7));if(board!=null&&prior!=null&&board.facing==prior.facing&&Arrays.equals(board.data,prior.data)){RoofCell c=q.next.cells.get(e.getKey());if(part.kind==RoofPart.SOFFIT&&c!=null&&c.parts.stream().anyMatch(a->a.kind==RoofPart.SOFFIT))continue;List<RoofPart> ps=new ArrayList<>(c==null?Collections.emptyList():c.parts);ps.add(part);q.next.cells.put(e.getKey(),new RoofCell(proposed.id,BlockPos.fromLong(e.getKey()),ps,c==null?Collections.emptyList():c.windows));}}
        Map<String,RoofWindow> posed=new TreeMap<>();for(RoofCell c:q.next.cells.values())for(RoofWindow n:c.windows)posed.putIfAbsent(n.id,n);Map<Long,RoofCell> layout=RoofWindowGeometry.layout(q.next.id,q.next.cells,posed.values());q.next.cells.clear();q.next.cells.putAll(layout);if(q.next.cells.size()>RoofPlan.MAX_CELLS){q.error="The roof and open windows exceed the cell limit.";return q;}
        for(RoofCell c:q.next.cells.values())for(RoofPart part:c.parts)if(!(part.kind==RoofPart.COVER&&part.material==0)&&RoofMaterials.item(part)==null){q.error="This feature requires a disabled material family.";return q;}
        Set<Long> touched=new TreeSet<>();Set<Long> all=new TreeSet<>(q.old.cells.keySet());all.addAll(q.next.cells.keySet());for(long key:all)if(!Objects.equals(q.old.cells.get(key),q.next.cells.get(key)))touched.add(key);
        // A paid unit is indivisible. Include every fragment sharing a touched unit.
        boolean more=true;Set<String> ids=new HashSet<>();while(more){more=false;for(long key:touched){RoofCell old=q.old.cells.get(key),next=q.next.cells.get(key);if(old!=null)for(RoofPart p:paid(old,w.getBlockState(BlockPos.fromLong(key)),BlockPos.fromLong(key)))ids.add(p.id);if(next!=null)for(RoofPart p:next.parts)ids.add(p.id);}for(long key:all)if(!touched.contains(key)){RoofCell old=q.old.cells.get(key),next=q.next.cells.get(key);boolean joins=false;if(old!=null)for(RoofPart p:paid(old,w.getBlockState(BlockPos.fromLong(key)),BlockPos.fromLong(key)))joins|=ids.contains(p.id);if(next!=null)for(RoofPart p:next.parts)joins|=ids.contains(p.id);if(joins){touched.add(key);more=true;}}}
        for(long key:touched){BlockPos at=BlockPos.fromLong(key);if(!w.isBlockLoaded(at)){q.error="Bring all affected roof sections into loaded chunks.";return q;}IBlockState state=w.getBlockState(at);RoofCell old=q.old.cells.get(key);if(old!=null&&!RoofDesignInteraction.host(state)||old==null&&!w.isAirBlock(at)){q.error="Clear the obstruction at "+at.getX()+", "+at.getY()+", "+at.getZ()+".";return q;}if(player!=null&&(!w.isBlockModifiable(player,at)||!player.canPlayerEdit(at,EnumFacing.UP,new ItemStack(ArchitectureBlocks.ROOF_TIMBER)))){q.error="You cannot build at one of the affected positions.";return q;}RoofCell next=q.next.cells.get(key);if(next!=null&&blocked(w,at,next)){q.error="Move clear of the proposed construction.";return q;}if(old!=null)q.remove.add(key);if(next!=null)q.place.add(key);}
        Map<String,ItemStack> before=resources(w,q.old.cells,touched),after=resources(w,q.next.cells,touched);RoofMaterials.Stock available=new RoofMaterials.Stock(),wanted=new RoofMaterials.Stock();for(ItemStack s:before.values())available.add(s,1);for(ItemStack s:after.values())wanted.add(s,1);for(ItemStack s:wanted.list()){int n=Math.min(s.stackSize,available.count(s));q.reuse.add(s,n);available.take(s,n);q.additions.add(s,s.stackSize-n);}q.returns.items.putAll(available.items);
        // Place owner cells first so a partially completed window retains its paid root.
        q.place.sort(Comparator.comparingInt(k->{RoofCell c=q.next.cells.get(k);for(RoofWindow n:c.windows)if(n.owner.toLong()==k)return 0;return 1;}));return q;
    }
    private static boolean blocked(World w,BlockPos at,RoofCell c){for(Entity e:w.getEntitiesWithinAABB(Entity.class,new AxisAlignedBB(at,at.add(1,1,1))))if(!e.isDead&&!e.noClip&&e.canBeCollidedWith())for(AxisAlignedBB box:RoofMeshes.get(c,0).boxes)if(box.offset(at).intersectsWith(e.getEntityBoundingBox()))return true;return false;}
    public static boolean supplied(Desk d,Quote q){if(!q.error.isEmpty())return false;for(ItemStack s:q.additions.list()){int count=s.getItem()==ArchitectureBlocks.ROOF_TIMBER?RoofConstruction.available(d,s.getMetadata()):d.count(s.getItem(),s.getMetadata());if(count<s.stackSize)return false;}return true;}
    public static boolean start(Desk d,EntityPlayer player){if(RoofConstruction.busy(d.getWorld(),d.drawing.id)){d.status="Another workbench is building this drawing.";return false;}RoofPlanner.solve(d.drawing);Quote q=quote(d,d.drawing,player);if(!q.error.isEmpty()){d.status=q.error;return false;}boolean free=player!=null&&player.capabilities.isCreativeMode;if(!free&&!supplied(d,q)){d.status="Supply the missing materials shown in the bill.";return false;}Job job=new Job();if(!free)for(ItemStack s:q.additions.list()){if(s.getItem()==ArchitectureBlocks.ROOF_TIMBER){int n=Math.min(s.stackSize,d.count(s.getItem(),s.getMetadata()));d.take(s.getItem(),s.getMetadata(),n);int pairs=(s.stackSize-n+1)/2;d.take(Item.getItemFromBlock(Blocks.PLANKS),s.getMetadata(),pairs);d.take(Items.STICK,-1,pairs);if(n+2*pairs>s.stackSize)d.give(new ItemStack(ArchitectureBlocks.ROOF_TIMBER,1,s.getMetadata()));}else d.take(s.getItem(),s.getMetadata(),s.stackSize);job.escrow.add(s,s.stackSize);}
        d.drawing=q.next;d.prior=q.old;d.operations.clear();d.operations.addAll(q.remove);job.removals=q.remove.size();d.operations.addAll(q.place);d.index=0;d.creative=free;d.remaining=0;d.job=job;d.active=true;d.preview=false;d.status="Reworking the changed sections...";d.markDirty();RoofConstruction.enqueue(d);return true;}
    private static void index(Desk d){Job j=d.job;if(j.indexed)return;for(int i=d.index;i<j.removals;i++){long key=d.operations.get(i);RoofCell c=d.prior.cells.get(key);Set<String> cellIds=new HashSet<>();if(c!=null)for(RoofPart p:paid(c,d.getWorld().getBlockState(BlockPos.fromLong(key)),BlockPos.fromLong(key))){ItemStack item=RoofMaterials.item(p);if(item!=null&&cellIds.add(p.id)){j.left.merge(p.id,1,Integer::sum);j.recovered.put(p.id,item);}}}j.indexed=true;}
    public static boolean step(Desk d){Job j=d.job;World w=d.getWorld();if(d.index>=d.operations.size()){if(!d.creative)for(ItemStack s:j.escrow.list())d.give(s);d.active=false;d.job=null;d.prior=null;d.status="Roof complete.";RoofData.get(w).savePlan(d.drawing);d.markDirty();return true;}index(d);long key=d.operations.get(d.index);BlockPos at=BlockPos.fromLong(key);if(!w.isBlockLoaded(at)){d.status="Paused: a roof chunk is unloaded.";return false;}RoofCell actual=RoofData.get(w).at(w,at);boolean removing=d.index<j.removals;RoofCell expected=removing?d.prior.cells.get(key):d.drawing.cells.get(key);if(removing?actual==null||!actual.equals(expected):!w.isAirBlock(at)){d.status="Paused: an affected position changed. Clear it or cancel.";return false;}if(!removing&&blocked(w,at,expected)){d.status="Paused: someone is in the way.";return false;}
        RoofConstruction.changing=true;try{if(removing){for(RoofPart p:paid(actual,w.getBlockState(at),at))if(j.left.containsKey(p.id)){int n=j.left.get(p.id)-1;j.left.put(p.id,n);if(n==0&&!d.creative)j.escrow.add(j.recovered.get(p.id),1);}RoofData.get(w).put(w,at,null);w.setBlockToAir(at);}else{for(RoofPart p:expected.parts){ItemStack item=RoofMaterials.item(p);if(item!=null&&!j.spent.contains(p.id)){if(!d.creative&&!j.escrow.take(item,1))throw new IllegalStateException("Missing reserved roof material "+p.id);j.spent.add(p.id);}}for(RoofWindow window:expected.windows)if(window.owner.equals(at))RoofData.get(w).restoreWindow(expected.plan,window.id);RoofData.get(w).put(w,at,expected);w.setBlockState(at,RoofDesignInteraction.state(expected,at),3);}}finally{RoofConstruction.changing=false;}w.checkLight(at);d.index++;RoofConstruction.changes++;d.markDirty();return true;
    }
    public static void cancel(Desk d){if(d.job!=null&&!d.creative)for(ItemStack s:d.job.escrow.list())d.give(s);d.job=null;}
}
